package org.securemail.identity;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.io.TempDir;
import org.securemail.ecosystem.protocol.IdentityProtocol;
import org.securemail.ecosystem.protocol.IdentityProtocol.*;
import java.nio.file.*;
import java.security.*;
import java.util.*;
import java.net.*;
import java.net.http.*;
import java.util.concurrent.*;
import static org.junit.jupiter.api.Assertions.*;

/** Unknown-device proof authenticates only a public existing challenge, never recovery metadata or enrollment. */
class DeviceRecoveryInspectionTest {
 @TempDir Path home;IdentityStoreTest f;KeyPair next;DeviceRecovery recovery;
 @BeforeEach void setup()throws Exception{f=new IdentityStoreTest();f.home=home;f.setup();next=IdentityStoreTest.pair();String n=IdentityProtocol.nonce();byte[] b=IdentityProtocol.login(f.store.audience(),f.account,IdentityProtocol.id(IdentityStoreTest.key(next)),f.clock.millis(),n);var c=f.store.challengeDevice(f.account,IdentityStoreTest.key(next),f.clock.millis(),n,IdentityProtocol.sign(next.getPrivate(),b));recovery=new DeviceRecovery(f.store.audience(),f.account,c.deviceKey(),c.challenge(),c.expiresAt());}
 @AfterEach void close()throws Exception{f.close();}
 Map<String,Object> query(DeviceRecovery r,String n){return Map.of("recovery",IdentityProtocol.b64(IdentityProtocol.deviceRecoveryBytes(r)),"time",f.clock.millis(),"nonce",n,"proof",IdentityProtocol.b64(IdentityProtocol.sign(next.getPrivate(),IdentityProtocol.deviceRecoveryInspection(r,f.clock.millis(),n))));}
 Map<String,Object> inspect(IdentityStore store,DeviceRecovery r,Map<String,Object> d){return store.inspectDeviceRecovery(r,(Long)d.get("time"),(String)d.get("nonce"),IdentityProtocol.unb64((String)d.get("proof"),64));}
 @Test void actualSignedHttpPublicOnlyInspectionThenRegisteredDualProofRecovery()throws Exception{Capability old=f.cap(App.MAIL,EnumSet.of(Scope.MAIL_READ));try(IdentityHttpServer server=new IdentityHttpServer(new InetSocketAddress("127.0.0.1",0),f.store,f.service)){server.start();Map<String,Object> d=query(recovery,IdentityProtocol.nonce()),out=rpc(server,"deviceRecoveryInspect",d);assertEquals(Set.of("recovery","accountId","challenge","expiresAt","audience","deviceKey"),out.keySet());assertFalse(out.containsKey("recoveryPublic"));assertFalse(out.containsKey("accountPublicKey"));assertFalse(out.containsKey("generation"));assertArrayEquals(IdentityProtocol.deviceRecoveryBytes(recovery),IdentityProtocol.unb64((String)out.get("recovery"),1024));assertTrue(f.store.isActive(old));assertThrows(IdentityException.class,()->f.login(next));byte[] body=IdentityProtocol.deviceRecoveryBytes(recovery);assertEquals(true,rpc(server,"recoverDevice",Map.of("accountId",f.account,"challenge",recovery.challenge,"accountProof",IdentityProtocol.b64(IdentityProtocol.sign(f.root.getPrivate(),body)),"recoveryProof",IdentityProtocol.b64(IdentityProtocol.sign(f.recovery.getPrivate(),body)))).get("sensitiveRecoveryPending"));assertFalse(f.store.isActive(old));assertEquals(f.account,f.login(next).accountId());assertEquals(true,f.store.profile(f.account).get("sensitiveRecoveryPending"));assertThrows(IdentityException.class,()->rpc(server,"deviceRecoveryInspect",query(recovery,IdentityProtocol.nonce())));assertTrue(f.store.verifyAudit());}}
 @Test void newDeviceProofCannotBeReusedForDifferentKeyAccountAudienceOrExpiry()throws Exception{for(DeviceRecovery changed:List.of(new DeviceRecovery("0".repeat(64),f.account,recovery.newDevicePublic(),recovery.challenge,recovery.expiresAt),new DeviceRecovery(recovery.audience,"0".repeat(64),recovery.newDevicePublic(),recovery.challenge,recovery.expiresAt),new DeviceRecovery(recovery.audience,f.account,recovery.newDevicePublic(),recovery.challenge,recovery.expiresAt+1),new DeviceRecovery(recovery.audience,f.account,IdentityStoreTest.key(IdentityStoreTest.pair()),recovery.challenge,recovery.expiresAt))){assertThrows(IdentityException.class,()->inspect(f.store,changed,query(changed,IdentityProtocol.nonce())));}String n=IdentityProtocol.nonce();assertThrows(IdentityException.class,()->f.store.inspectDeviceRecovery(recovery,f.clock.millis(),n,IdentityProtocol.sign(f.device.getPrivate(),IdentityProtocol.deviceRecoveryInspection(recovery,f.clock.millis(),n))));assertThrows(IdentityException.class,()->f.store.inspectDeviceRecovery(recovery,f.clock.millis(),n,IdentityProtocol.sign(next.getPrivate(),IdentityProtocol.deviceRecoveryBytes(recovery))));}
 @Test void replayedInspectionDoesNotEnrollOrConsumeTheActualRecoveryChallenge(){Map<String,Object>d=query(recovery,IdentityProtocol.nonce());inspect(f.store,recovery,d);assertEquals("REPLAY",assertThrows(IdentityException.class,()->inspect(f.store,recovery,d)).code());assertThrows(IdentityException.class,()->f.login(next));inspect(f.store,recovery,query(recovery,IdentityProtocol.nonce()));assertEquals(false,f.store.profile(f.account).get("sensitiveRecoveryPending"));}
 @Test void staleRecoveryFileCannotChangeDeviceTrustBeforeCorrectRegisteredProof()throws Exception{byte[] b=IdentityProtocol.deviceRecoveryBytes(recovery);KeyPair wrong=IdentityStoreTest.pair();assertThrows(IdentityException.class,()->f.store.recoverDevice(f.account,recovery.challenge,IdentityProtocol.sign(f.root.getPrivate(),b),IdentityProtocol.sign(wrong.getPrivate(),b)));assertThrows(IdentityException.class,()->f.login(next));assertEquals(false,f.store.profile(f.account).get("sensitiveRecoveryPending"));f.store.recoverDevice(f.account,recovery.challenge,IdentityProtocol.sign(f.root.getPrivate(),b),IdentityProtocol.sign(f.recovery.getPrivate(),b));assertEquals(f.account,f.login(next).accountId());}
 @Test void exactExpiryAndClockRollbackFailClosed(){f.clock.value++;inspect(f.store,recovery,query(recovery,IdentityProtocol.nonce()));f.clock.value--;assertEquals("CLOCK_ROLLBACK",assertThrows(IdentityException.class,()->inspect(f.store,recovery,query(recovery,IdentityProtocol.nonce()))).code());f.clock.value=recovery.expiresAt;assertThrows(IdentityException.class,()->inspect(f.store,recovery,query(recovery,IdentityProtocol.nonce())));}
 @Test void consumedTrustedDeviceApprovalChallengeCannotBeInspected(){f.step();byte[] bytes=IdentityProtocol.deviceApproval(f.store.audience(),f.account,f.deviceId,recovery.challenge,recovery.newDevicePublic(),recovery.expiresAt);f.store.approveDevice(f.account,f.deviceId,f.session.generation(),recovery.challenge,IdentityProtocol.sign(f.device.getPrivate(),bytes));assertThrows(IdentityException.class,()->inspect(f.store,recovery,query(recovery,IdentityProtocol.nonce())));}
 @Test void dtoDefensiveKeyAndCanonicalDomainRemainExact(){byte[] key=recovery.newDevicePublic();key[0]^=1;assertArrayEquals(IdentityStoreTest.key(next),recovery.newDevicePublic());byte[] encoded=IdentityProtocol.deviceRecoveryBytes(recovery);assertArrayEquals(encoded,IdentityProtocol.deviceRecoveryBytes(IdentityProtocol.decodeDeviceRecovery(encoded)));assertThrows(IllegalArgumentException.class,()->IdentityProtocol.decodeDeviceRecovery(Arrays.copyOf(encoded,encoded.length+1)));assertThrows(IllegalArgumentException.class,()->IdentityProtocol.decodeOwnerBootstrap(encoded));}
 @Test void twoSqlConnectionsConsumeInspectionNonceOnlyOnce()throws Exception{Map<String,Object> d=query(recovery,IdentityProtocol.nonce());try(IdentityStore other=new IdentityStore(home.resolve("identity.db"),f.service,f.audit,f.clock)){ExecutorService workers=Executors.newFixedThreadPool(2);try{CountDownLatch start=new CountDownLatch(1);java.util.function.Function<IdentityStore,Boolean> check=s->{try{inspect(s,recovery,d);return true;}catch(IdentityException denied){return false;}};Future<Boolean>a=workers.submit(()->{start.await();return check.apply(f.store);}),b=workers.submit(()->{start.await();return check.apply(other);});start.countDown();assertNotEquals(a.get(5,TimeUnit.SECONDS),b.get(5,TimeUnit.SECONDS));assertThrows(IdentityException.class,()->f.login(next));}finally{workers.shutdownNow();}}}
 Map<String,Object> rpc(IdentityHttpServer server,String operation,Map<String,Object> data)throws Exception{String nonce=IdentityProtocol.nonce();byte[] request=IdentityJson.bytes(Map.of("operation",operation,"nonce",nonce,"data",data));HttpResponse<byte[]> r=HttpClient.newHttpClient().send(HttpRequest.newBuilder(URI.create("http://127.0.0.1:"+server.port()+"/identity/v1")).header("Content-Type","application/json").POST(HttpRequest.BodyPublishers.ofByteArray(request)).timeout(java.time.Duration.ofSeconds(3)).build(),HttpResponse.BodyHandlers.ofByteArray());assertTrue(IdentityProtocol.verify(IdentityStoreTest.key(f.service),IdentityProtocol.response(f.store.audience(),nonce,request,r.body()),IdentityProtocol.unb64(r.headers().firstValue("AEGIS-Signature").orElseThrow(),64)));Map<String,Object> response=IdentityJson.parse(r.body());if(!Boolean.TRUE.equals(response.get("ok")))throw new IdentityException((String)((Map<?,?>)response.get("error")).get("code"));@SuppressWarnings("unchecked")Map<String,Object> result=(Map<String,Object>)response.get("data");return result;}
}
